 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Locate 3x3 ring objects (3 border, 2 center).
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if g[r][c] == 2 and all(
                g[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    # The repeated 2-lines are the parallel rails. Choose their orientation.
    dense_rows = [r for r in range(h) if sum(v == 2 for v in g[r]) >= max(4, w // 3)]
    dense_cols = [c for c in range(w) if sum(g[r][c] == 2 for r in range(h)) >= max(4, h // 3)]
    horizontal_rails = len(dense_rows) >= 2 and len(dense_rows) >= len(dense_cols)
    rails = dense_rows if horizontal_rails else dense_cols

    def paint(r, c):
        if 0 <= r < h and 0 <= c < w and g[r][c] == 0:
            g[r][c] = 1

    centers_set = set(centers)
    for r, c in centers:
        if horizontal_rails:
            # Continue the object's center axis perpendicular to the rails.
            for rr in range(h):
                paint(rr, c)
            # The center ring is echoed at each other rail crossing.
            for rr in rails:
                if (rr, c) not in centers_set:
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if (dr, dc) != (0, 0):
