                paint(r, cc)
            for cc in rails:
                if (r, cc) not in centers_set:
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if (dr, dc) != (0, 0):
                                paint(r + dr, cc + dc)
    return g
